pub fn is_palindrome(text: Vec<char>) -> (bool) {
    // ASCII-only lowercasing: 'A'..='Z' -> 'a'..='z', everything else unchanged.
    fn ascii_lower(c: char) -> char {
        if ('A'..='Z').contains(&c) {
            // Safe: for ASCII uppercase letters, adding 32 yields the lowercase letter.
            ((c as u8) + 32) as char
        } else {
            c
        }
    }

    let n = text.len();
    for i in 0..(n / 2) {
        if ascii_lower(text[i]) != ascii_lower(text[n - 1 - i]) {
            return (false);
        }
    }
    (true)
}

